class Solution:
    def generateTrees(self, n: int):
        def build(lo, hi):
            if lo > hi:
                return [None]
            trees = []
            for i in range(lo, hi + 1):
                for left in build(lo, i - 1):
                    for right in build(i + 1, hi):
                        root = TreeNode(i, left, right)
                        trees.append(root)
            return trees
        return build(1, n) if n else []

